      muted: "var(--scraps-theme-border-secondary)",
      accent: { vibrant: "var(--scraps-theme-border-accent)" },
      danger: { vibrant: "var(--scraps-theme-border-danger)" },
      promotion: { vibrant: "var(--scraps-theme-border-promotion)" },
